import crypto from 'node:crypto';
import { HttpError } from './http.js';
import {
  NETCASH_DEFAULT_SVK,
  batchFileUpload,
  requestFileUploadReport,
  debiCheckAmendAuthentication,
  bankAccountTypeCode,
  bankAccountTypeName,
  yyyymmdd
} from './netcash.js';
import { requestActionDate, requestPresentationDate } from './netcash-reconciliation.js';
import { ensureNetcashAvsForLoan } from './netcash-avs.js';
import { loadNetcashCredentials } from './provider-secrets.js';
import { dbInsert, dbRpc, dbSelect, dbUpdate, supabaseRequest } from './supabase-rest.js';

const NIF_URL='https://ws.netcash.co.za/NIWS/NIWS_NIF.svc';
const VALIDATION_URL='https://ws.netcash.co.za/NIWS/NIWS_Validation.svc';
const PAYNOW_URL='https://ws.netcash.co.za/PayNow/PayNow.svc';
const SECURITY_URL='https://ws.netcash.co.za/CDN/SecurityService.asmx';
const PAYNOW_FORM_URL='https://paynow.netcash.co.za/site/paynow.aspx';
const PAYNOW_QR_URL='https://paynow.netcash.co.za/Site/PayNowQR.aspx';
const TOKEN_BASE_URL='https://cde.netcash.co.za/Site/';
const GUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const UUID=GUID;

function xml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function unxml(value){return String(value??'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');}
function tag(source,name){const m=String(source||'').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'i'));return m?unxml(m[1].trim()):null;}
function blocks(source,name){return[...String(source||'').matchAll(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'gi'))].map(m=>m[1]);}
function allTags(source,name){return blocks(source,name).map(v=>unxml(v.trim())).filter(Boolean);}
function parseMoney(value){const n=Number(String(value??'').replace(',','.').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null;}
function randomRef(prefix='KR'){return `${prefix}${Date.now().toString(36).toUpperCase()}${crypto.randomBytes(4).toString('hex').toUpperCase()}`.slice(0,25);}
function sha(value){return crypto.createHash('sha256').update(String(value||'')).digest('hex');}
function zaToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Johannesburg',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function compactStatus(raw){const t=String(raw||'').trim();if(!t||/FILE NOT READY/i.test(t))return{ready:false,status:'file_not_ready'};const begin=t.split(/\r?\n/).find(l=>l.startsWith('###BEGIN'))||'';const state=String(begin.split('\t')[2]||'').trim().toUpperCase();if(state==='SUCCESSFUL')return{ready:true,status:'successful'};if(state==='SUCCESSFUL WITH ERRORS')return{ready:true,status:'successful_with_errors'};if(state==='UNSUCCESSFUL'||t.includes('###ERROR')||/^(100|102|200)$/.test(t))return{ready:true,status:'unsuccessful'};return{ready:false,status:'processing'};}
function soapError(text,status,label='Netcash'){return new HttpError(status>=500?502:400,tag(text,'faultstring')||tag(text,'Text')||tag(text,'Reason')||`${label} returned HTTP ${status}.`,'netcash_error');}

async function soap11(endpoint,method,body,namespace='http://tempuri.org/',timeout=30000){
  const action=`${namespace}${method}`;
  const envelope=`<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><${method} xmlns="${namespace}">${body}</${method}></soap:Body></soap:Envelope>`;
  const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/xml; charset=utf-8',SOAPAction:`"${action}"`},body:envelope,signal:AbortSignal.timeout(timeout)});
  const text=await response.text();if(!response.ok||/<(?:\w+:)?Fault[\s>]/i.test(text))throw soapError(text,response.status,method);return text;
}
async function nif(method,params,{methodParameters=false,timeout=30000}={}){const fields=Object.entries(params).map(([k,v])=>`<${k}>${xml(v)}</${k}>`).join('');return soap11(NIF_URL,method,methodParameters?`<MethodParameters>${fields}</MethodParameters>`:fields,'http://tempuri.org/NIWS_NIF/',timeout);}
async function validation(method,params){const fields=Object.entries(params).map(([k,v])=>`<${k}>${xml(v)}</${k}>`).join('');return soap11(VALIDATION_URL,method,fields,'http://tempuri.org/NIWS_Validation/',20000);}
async function payNow(method,params){const fields=Object.entries(params).map(([k,v])=>`<${k}>${xml(v)}</${k}>`).join('');return soap11(PAYNOW_URL,method,fields,'http://tempuri.org/IPayNow/',30000);}

async function context(){const[rows,credentials]=await Promise.all([dbSelect('netcash_config',{select:'*',id:'eq.true',limit:1}),loadNetcashCredentials()]);return{config:rows?.[0]||{},credentials:credentials||{}};}
function requireEnabled(config){if(!config.enabled||config.validation_status!=='validated')throw new HttpError(409,'Netcash must be connected and validated first.','netcash_not_ready');}
function requireKey(credentials,key,label){const value=credentials?.[key];if(!GUID.test(String(value||'')))throw new HttpError(409,`${label} is not configured in Netcash Settings.`,'netcash_service_key_required');return value;}

export async function getNetcashAccountControls(){
  const{config,credentials}=await context();requireEnabled(config);const accountKey=requireKey(credentials,'accountServiceKey','Account Service Key');
  const balanceXml=await nif('GetAvailableBalance',{ServiceKey:accountKey},{methodParameters:true});
  const errorCode=tag(balanceXml,'ErrorCode');if(errorCode&&errorCode!=='000')throw new HttpError(409,`Netcash balance check failed (${errorCode}).`,'netcash_balance_failed');
  let paymentLimits=null,debitLimits=null;
  if(credentials.creditorServiceKey){const x=await nif('GetPaymentLimits',{ServiceKey:credentials.creditorServiceKey},{methodParameters:true});paymentLimits={errorCode:tag(x,'ErrorCode'),lineLimit:parseMoney(tag(x,'LineLimit')),batchLimit:parseMoney(tag(x,'BatchLimit'))};}
  if(credentials.debitOrderServiceKey){const x=await nif('GetDebitLimits',{ServiceKey:credentials.debitOrderServiceKey},{methodParameters:true});debitLimits={errorCode:tag(x,'ErrorCode'),lineLimit:parseMoney(tag(x,'LineLimit')),dailyLimit:parseMoney(tag(x,'DailyLimit')||tag(x,'BatchLimit'))};}
  return{availableBalance:parseMoney(tag(balanceXml,'AvailableBalance')),currentBalance:parseMoney(tag(balanceXml,'CurrentBalance')),paymentLimits,debitLimits};
}

function creditorInstruction(stream){return stream==='rtc'?'RTCPayments':stream==='dated'?'DatedPayments':'Realtime';}
function buildCreditorFile({serviceKey,svk,batchName,actionDate,payout,loan,profile}){
  const keys=[101,102,131,132,133,134,135,136,162,201,202,252,301,302,303];
  const holder=String(profile.bank_account_holder||`${profile.first_name||''} ${profile.last_name||''}`).trim();
  const row=[`K\t${keys.join('\t')}`,
    ['T',loan.account_number||payout.id,String(`${profile.first_name||''} ${profile.last_name||''}`).trim(),1,holder,bankAccountTypeCode(profile.bank_account_type),String(profile.branch_code||'').replace(/\D/g,'').padStart(6,'0'),0,String(profile.bank_account_number||'').replace(/\D/g,''),Math.round(Number(payout.amount)*100),profile.email||'',String(profile.mobile||'').replace(/\D/g,'').slice(-10),String(loan.account_number||'KredRun loan').slice(0,20),payout.id,loan.id,loan.user_id].join('\t')];
  return [`H\t${serviceKey}\t1\t${creditorInstruction(payout.stream)}\t${batchName}\t${yyyymmdd(actionDate)}\t${svk||NETCASH_DEFAULT_SVK}`,...row,'F\t1\t0\t9999'].join('\n');
}

async function findUnauthorisedBatch(serviceKey,batchName){
  const text=await nif('RetrieveUnauthorisedBatches',{ServiceKey:serviceKey});const result=tag(text,'RetrieveUnauthorisedBatchesResult')||tag(text,'String')||text;
  for(const line of String(result).split(/\r?\n/)){const f=line.split('\t');if(f.includes(batchName)||String(line).includes(batchName))return{batchId:String(f[1]||f[0]||'').trim(),raw:line};}return null;
}
export async function authoriseNetcashBatch(serviceKey,batchName){
  const{config}=await context();if(!config.auto_batch_authorization_enabled||!config.auto_batch_authorization_indemnity_confirmed)throw new HttpError(409,'Automatic batch authorisation is not enabled and indemnity-confirmed for this Netcash account.','netcash_auto_authorisation_not_enabled');
  const batch=await findUnauthorisedBatch(serviceKey,batchName);if(!batch?.batchId)throw new HttpError(409,'Netcash did not return this batch as unauthorised.','netcash_batch_not_found');
  const text=await nif('RequestBatchAuthorise',{ServiceKey:serviceKey,BatchId:batch.batchId});const result=String(tag(text,'RequestBatchAuthoriseResult')||'').trim();
  if(result&&result!=='000'&&!/success/i.test(result))throw new HttpError(409,`Netcash could not authorise the batch (${result}).`,'netcash_batch_authorise_failed');return{batchId:batch.batchId,result:result||'000'};
}

export async function disburseNetcashLoan({loanId,stream=null,createdBy=null}){
  const{config,credentials}=await context();requireEnabled(config);if(!config.creditor_payments_enabled)throw new HttpError(409,'Netcash Creditor Payments are disabled in Settings.','netcash_creditor_disabled');
  const creditorKey=requireKey(credentials,'creditorServiceKey','Creditor Payments Service Key');
  const existing=await dbSelect('netcash_payouts',{select:'*',loan_id:`eq.${loanId}`,limit:1});if(existing?.[0]&&['queued','unauthorised','authorised','processing','paid'].includes(existing[0].status))return{idempotent:true,payout:existing[0]};
  const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0];if(!loan)throw new HttpError(404,'Loan not found.','loan_not_found');if(!['ready','pending'].includes(loan.payout_status))throw new HttpError(409,'This loan is not ready for disbursement.','loan_not_ready_for_payout');
  const profile=(await dbSelect('customer_profiles',{select:'*',id:`eq.${loan.user_id}`,limit:1}))?.[0];if(!profile)throw new HttpError(409,'Client profile is missing.','client_profile_required');
  const missing=['bank_account_holder','bank_account_number','branch_code','bank_account_type'].filter(k=>!String(profile[k]||'').trim());if(missing.length)throw new HttpError(409,`Payout needs ${missing.join(', ')}.`,'payout_bank_details_incomplete');
  if(config.require_avs_before_payout)await ensureNetcashAvsForLoan(loan.id);
  const amount=Number(loan.principal_amount);const controls=(config.require_balance_check_before_payout||config.require_payment_limits_check_before_payout)?await getNetcashAccountControls():null;
  if(config.require_balance_check_before_payout&&controls?.availableBalance!==null&&controls.availableBalance<amount)throw new HttpError(409,`Netcash available balance is insufficient for this R${amount.toFixed(2)} payout.`,'netcash_insufficient_balance');
  if(config.require_payment_limits_check_before_payout&&controls?.paymentLimits?.lineLimit&&amount>controls.paymentLimits.lineLimit)throw new HttpError(409,'The payout exceeds the Netcash creditor-payment line limit.','netcash_payout_limit_exceeded');
  const payoutStream=stream||config.default_payout_stream||'rtc';if(!['rtc','same_day','dated'].includes(payoutStream))throw new HttpError(400,'Choose RTC, Same-Day or Dated payout.','invalid_payout_stream');
  const requested=zaToday();const actionDate=await requestActionDate(creditorKey,requested,creditorInstruction(payoutStream),true)||requested;const presentationDate=await requestPresentationDate(creditorKey,actionDate,creditorInstruction(payoutStream));
  const rows=await supabaseRequest('/rest/v1/netcash_payouts?on_conflict=loan_id',{method:'POST',body:{loan_id:loan.id,user_id:loan.user_id,amount,stream:payoutStream,status:'initializing',action_date:actionDate,presentation_date:presentationDate,created_by:createdBy,updated_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=representation'});const payout=rows?.[0];
  const batchName=`KR-PAYOUT-${String(loan.account_number||loan.id).replace(/[^A-Za-z0-9]/g,'').slice(0,24)}-${Date.now().toString(36)}`.slice(0,50);
  try{
    const file=buildCreditorFile({serviceKey:creditorKey,svk:config.software_vendor_key,batchName,actionDate,payout,loan,profile});const fileToken=await batchFileUpload(creditorKey,file);const raw=await requestFileUploadReport(creditorKey,fileToken).catch(()=> 'FILE NOT READY');const report=compactStatus(raw);
    if(report.ready&&report.status==='unsuccessful')throw new HttpError(409,'Netcash rejected the creditor payout batch.','netcash_payout_load_failed');
    let auth={status:'required',batchId:null};
    if(config.auto_batch_authorization_enabled&&config.auto_batch_authorization_indemnity_confirmed){try{const a=await authoriseNetcashBatch(creditorKey,batchName);auth={status:'authorised',batchId:a.batchId};}catch(error){auth={status:'required',error:error.message};}}
    const updated=(await dbUpdate('netcash_payouts',{id:`eq.${payout.id}`},{status:auth.status==='authorised'?'authorised':'unauthorised',batch_name:batchName,file_token:fileToken,batch_id:auth.batchId,authorisation_status:auth.status,load_status:report.status,provider_result:{load_report:String(raw).slice(0,12000),controls},submitted_at:new Date().toISOString(),updated_at:new Date().toISOString()}))?.[0];
    await dbUpdate('loans',{id:`eq.${loan.id}`},{payout_provider:'netcash',payout_provider_status:updated?.status||'unauthorised',updated_at:new Date().toISOString()});return{payout:updated||payout,controls};
  }catch(error){await dbUpdate('netcash_payouts',{id:`eq.${payout.id}`},{status:'failed',last_error:String(error.message||error).slice(0,500),updated_at:new Date().toISOString()}).catch(()=>{});throw error;}
}

export async function retrieveNetcashProofOfPayment(payoutId){
  const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'creditorServiceKey','Creditor Payments Service Key');const payout=(await dbSelect('netcash_payouts',{select:'*',id:`eq.${payoutId}`,limit:1}))?.[0];if(!payout?.transaction_id)throw new HttpError(409,'A reconciled Netcash transaction ID is required before proof of payment can be downloaded.','payout_transaction_required');
  const text=await nif('RetrieveProofOfPayment',{ServiceKey:key,TransactionId:payout.transaction_id},{methodParameters:true});const errorCode=tag(text,'ErrorCode');if(errorCode&&errorCode!=='000')throw new HttpError(409,`Netcash proof-of-payment request failed (${errorCode}).`,'netcash_pop_failed');const pdf=tag(text,'ProofOfPaymentPDF')||tag(text,'String');if(!pdf)throw new HttpError(502,'Netcash did not return a proof-of-payment document.','netcash_pop_empty');await dbUpdate('netcash_payouts',{id:`eq.${payout.id}`},{proof_of_payment_retrieved_at:new Date().toISOString(),updated_at:new Date().toISOString()});return{transactionId:payout.transaction_id,base64Pdf:pdf};
}

export async function syncDebiCheckParticipatingBanks(){
  const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'accountServiceKey','Account Service Key');const text=await validation('GetDebiCheckParticipatingBanks',{ServiceKey:key});const errorCode=tag(text,'ErrorCode')||tag(text,'GetDebiCheckParticipatingBanksResult');if(errorCode&&!['000'].includes(errorCode)&&!allTags(text,'BankName').length)throw new HttpError(409,`Netcash participating-bank lookup failed (${errorCode}).`,'netcash_banks_failed');const banks=[...new Set(allTags(text,'BankName').map(v=>v.toUpperCase()))];for(const bank of banks)await supabaseRequest('/rest/v1/netcash_participating_banks?on_conflict=bank_name',{method:'POST',body:{bank_name:bank,active:true,synced_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=minimal'});await dbUpdate('netcash_config',{id:'eq.true'},{participating_banks_last_synced_at:new Date().toISOString(),updated_at:new Date().toISOString()});return banks;
}

export async function amendNetcashDebiCheck({loanId,collectionAmount,maximumCollectionAmount}){
  const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const contract=(await dbSelect('netcash_contracts',{select:'*',loan_id:`eq.${loanId}`,limit:1}))?.[0];if(!contract||contract.collection_stream!=='debicheck'||contract.mandate_status!=='accepted'||!contract.provider_contract_reference)throw new HttpError(409,'Only an accepted DebiCheck mandate can be amended.','netcash_debicheck_not_amendable');const amount=Math.round(Number(collectionAmount)*100),max=Math.round(Number(maximumCollectionAmount??collectionAmount)*100);if(!(amount>0)||!(max>=amount))throw new HttpError(400,'Enter a valid collection and maximum collection amount.','invalid_amount');const result=await debiCheckAmendAuthentication(key,contract.provider_contract_reference,amount,max);if(result.errorCode!=='000')throw new HttpError(409,`Netcash rejected the DebiCheck amendment (${result.errorCode||'unknown'}).`,'netcash_debicheck_amend_failed');await dbUpdate('netcash_contracts',{id:`eq.${contract.id}`},{provider_metadata:{...(contract.provider_metadata||{}),last_amendment:{collection_amount:Number(collectionAmount),maximum_collection_amount:Number(maximumCollectionAmount??collectionAmount),at:new Date().toISOString()}},updated_at:new Date().toISOString()});return result;
}

function mandateFrequency(value){const v=String(value||'monthly').toLowerCase();if(v==='weekly')return'Weekly';if(v==='fortnightly')return'Biweekly';if(v==='once_off')return'Monthly';return'Monthly';}
export async function createSynchronousEMandate({loanId,includeDebiCheck=false}){
  const{config,credentials}=await context();requireEnabled(config);if(!config.emandate_enabled)throw new HttpError(409,'Netcash eMandate is disabled.','emandate_disabled');const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0];const profile=loan?(await dbSelect('customer_profiles',{select:'*',id:`eq.${loan.user_id}`,limit:1}))?.[0]:null;const schedule=loan?(await dbSelect('repayment_schedule',{select:'*',loan_id:`eq.${loan.id}`,order:'instalment_number.asc',limit:1}))?.[0]:null;if(!loan||!profile||!schedule)throw new HttpError(409,'Loan, profile and repayment schedule are required.','emandate_data_missing');const ref=`KR${String(loan.id).replace(/-/g,'').slice(0,20).toUpperCase()}`;const params={ServiceKey:key,AccountReference:ref,MandateName:`${profile.first_name||''} ${profile.last_name||''}`.trim(),MandateAmount:Number(loan.instalment_amount||schedule.amount_due).toFixed(2),IsConsumer:'true',FirstName:profile.first_name||'',Surname:profile.last_name||'',TradingName:'',RegistrationNumber:'',RegisteredName:'',MobileNumber:String(profile.mobile||'').replace(/\D/g,'').slice(-10),DebitFrequency:mandateFrequency(loan.repayment_frequency),CommencementMonth:Number(String(schedule.due_date).slice(5,7)),CommencementDay:String(schedule.due_date).slice(8,10),AgreementDate:yyyymmdd(loan.start_date||new Date()),AgreementReferenceNumber:loan.account_number||ref,CancellationNoticePeriod:20,PublicHolidayOption:'VeryNextOrdinaryBusinessDay',Notes:'KredRun loan repayment mandate',Field1:loan.id,Field2:loan.user_id,Field3:'KredRun',AllowVariableDebitAmounts:'true',BankDetailType:1,BankAccountName:profile.bank_account_holder||'',BankAccountNumber:profile.bank_account_number||'',BranchCode:String(profile.branch_code||'').replace(/\D/g,'').padStart(6,'0'),BankAccountType:bankAccountTypeName(profile.bank_account_type),IsIdNumber:'true',EmailAddress:profile.email||'',PhoneNumber:String(profile.mobile||'').replace(/\D/g,'').slice(-10),MandateActive:'true',RequestAVS:'false',AVSCheckNumber:profile.id_number||'',IncludeDebiCheck:includeDebiCheck?'true':'false',DebiCheckMandateTemplateId:includeDebiCheck?(config.debicheck_template_id||''):'',DebiCheckCollectionAmount:Number(loan.instalment_amount||schedule.amount_due).toFixed(2),DebiCheckFirstCollectionDiffers:'false',DebiCheckFirstCollectionAmount:Number(schedule.amount_due).toFixed(2),DebiCheckCollectionDayCode:yyyymmdd(schedule.due_date),AddToMasterFile:'1'};
  const text=await nif('AddMandate',params,{methodParameters:true,timeout:60000});const errorCode=tag(text,'ErrorCode'),mandateUrl=tag(text,'MandateUrl');if(errorCode!=='000'||!mandateUrl)throw new HttpError(409,`Netcash eMandate could not be created (${errorCode||'unknown'}).`,'emandate_sync_failed');const contract=(await dbSelect('netcash_contracts',{select:'*',loan_id:`eq.${loan.id}`,limit:1}))?.[0];if(contract)await dbUpdate('netcash_contracts',{id:`eq.${contract.id}`},{mandate_url:mandateUrl,mandate_status:'requested',requested_at:new Date().toISOString(),provider_metadata:{...(contract.provider_metadata||{}),synchronous_emandate:true},updated_at:new Date().toISOString()});return{errorCode,mandateUrl,accountReference:ref};
}

export async function requestEMandatePdf(loanId){
  const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const contract=(await dbSelect('netcash_contracts',{select:'*',loan_id:`eq.${loanId}`,limit:1}))?.[0];if(!contract?.account_reference)throw new HttpError(409,'No Netcash mandate exists for this loan.','emandate_missing');const batchName=`KR-MANDATE-PDF-${Date.now().toString(36)}`;const file=[`H\t${key}\t1\tRequestMandatePDF\t${batchName}\t${yyyymmdd()}\t${config.software_vendor_key||NETCASH_DEFAULT_SVK}`,'K\t101',`T\t${contract.account_reference}`,'F\t1\t0\t9999'].join('\n');const token=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,token).catch(()=> 'FILE NOT READY');if(compactStatus(load).status==='unsuccessful')throw new HttpError(409,'Netcash rejected the mandate PDF request.','emandate_pdf_request_failed');const text=await nif('RetrieveMandatePDF',{ServiceKey:key,FileToken:token});const result=tag(text,'RetrieveMandatePDFResult')||tag(text,'String')||'';if(/FILE NOT READY/i.test(result))return{pending:true,fileToken:token};let url=null;for(const line of String(result).split(/\r?\n/)){const f=line.split('\t');if(f[0]===contract.account_reference&&f[1]){url=f[1].trim();break;}}if(url)await dbUpdate('netcash_contracts',{id:`eq.${contract.id}`},{mandate_pdf_url:url,updated_at:new Date().toISOString()});return{pending:!url,fileToken:token,url};
}

export async function updateEMandateMasterfile(loanId){
  const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const contract=(await dbSelect('netcash_contracts',{select:'*',loan_id:`eq.${loanId}`,limit:1}))?.[0];if(!contract?.account_reference)throw new HttpError(409,'No Netcash eMandate exists for this loan.','emandate_missing');const batchName=`KR-MANDATE-MF-${Date.now().toString(36)}`;const file=[`H\t${key}\t1\tMandateToMasterfile\t${batchName}\t${yyyymmdd()}\t${config.software_vendor_key||NETCASH_DEFAULT_SVK}`,'K\t101',`T\t${contract.account_reference}`,'F\t1\t0\t9999'].join('\n');const token=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,token).catch(()=> 'FILE NOT READY');await dbUpdate('netcash_contracts',{id:`eq.${contract.id}`},{provider_metadata:{...(contract.provider_metadata||{}),masterfile_update:{file_token:token,load_status:compactStatus(load).status,at:new Date().toISOString()}},updated_at:new Date().toISOString()});return{fileToken:token,loadStatus:compactStatus(load).status};
}

function payNowFields({config,credentials,reference,amount,description,profile,loanId,scheduleId,tokenize=false,subscription=null}){const fields={M1:credentials.payNowServiceKey,M2:config.software_vendor_key||NETCASH_DEFAULT_SVK,p2:reference,p3:description,Amount:Number(amount).toFixed(2),m4:loanId||'',m5:scheduleId||'',m6:'KredRun',m9:profile?.email||'',m11:String(profile?.mobile||'').replace(/\D/g,'').slice(-10),m10:reference,m14:tokenize?'1':'0'};if(subscription){fields.m16='1';fields.m17=String(subscription.cycles);fields.m18=String(subscription.frequency);fields.m19=String(subscription.startDate).replace(/-/g,'');fields.m20=Number(subscription.amount).toFixed(2);}return fields;}
export async function createPayNowEcommerce({loanId,scheduleId=null,amount,subscription=null,createdBy=null}){
  const{config,credentials}=await context();requireEnabled(config);if(!config.paynow_ecommerce_enabled)throw new HttpError(409,'Pay Now eCommerce is disabled.','paynow_ecommerce_disabled');requireKey(credentials,'payNowServiceKey','Pay Now Service Key');if(subscription&&!config.paynow_subscriptions_enabled)throw new HttpError(409,'Netcash Subscription Billing is disabled.','paynow_subscription_disabled');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0];const profile=loan?(await dbSelect('customer_profiles',{select:'*',id:`eq.${loan.user_id}`,limit:1}))?.[0]:null;if(!loan||!profile)throw new HttpError(409,'Loan and client profile are required.','payment_context_missing');const ref=randomRef(subscription?'KRSUB':'KRECOM');const value=Number(amount);if(!(value>0))throw new HttpError(400,'Enter a valid payment amount.','invalid_amount');const fields=payNowFields({config,credentials,reference:ref,amount:value,description:`Loan payment ${loan.account_number||''}`.trim(),profile,loanId,scheduleId,tokenize:Boolean(subscription),subscription});const kind=subscription?'subscription':'ecommerce';await dbInsert('netcash_paynow_operations',{user_id:loan.user_id,loan_id:loan.id,schedule_id:scheduleId,kind,reference:ref,amount:value,status:subscription?'pending':'created',provider_metadata:{subscription:subscription||null},created_by:createdBy});return{action:PAYNOW_FORM_URL,method:'POST',target:'_top',fields,reference:ref};
}
export async function createPayNowQr({loanId,scheduleId=null,amount,createdBy=null}){
  const{config,credentials}=await context();requireEnabled(config);if(!config.paynow_qr_enabled)throw new HttpError(409,'Pay Now QR is disabled.','paynow_qr_disabled');const token=requireKey(credentials,'payNowMerchantToken','Pay Now Merchant Token');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0];if(!loan)throw new HttpError(404,'Loan not found.','loan_not_found');const ref=randomRef('KRQR'),value=Number(amount);const qs=new URLSearchParams({MerchantToken:token,M2:config.software_vendor_key||NETCASH_DEFAULT_SVK,Amount:value.toFixed(2),P2:ref,Extra1:loan.id,Extra2:scheduleId||'',Extra3:'KredRun'});await dbInsert('netcash_paynow_operations',{user_id:loan.user_id,loan_id:loan.id,schedule_id:scheduleId,kind:'qr',reference:ref,amount:value,status:'created',created_by:createdBy});return{reference:ref,url:`${PAYNOW_QR_URL}?${qs}`};
}
export async function updateNetcashSubscription({reference,cycles,frequency,startDate,amount,active=true,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.paynow_subscriptions_enabled)throw new HttpError(409,'Netcash Subscription Billing is disabled.','paynow_subscription_disabled');const key=requireKey(credentials,'payNowServiceKey','Pay Now Service Key');const text=await payNow('UpdateSubscriptions',{M1:key,P2:reference,M17:Number(cycles),M18:Number(frequency),M19:String(startDate).replace(/-/g,''),M20:Number(amount).toFixed(2),Active:active?'true':'false'});const result=String(tag(text,'UpdateSubscriptionsResult')||tag(text,'String')||'').trim();if(result!=='000')throw new HttpError(409,`Netcash subscription update failed (${result||'unknown'}).`,'netcash_subscription_update_failed');await dbInsert('netcash_paynow_operations',{kind:'subscription_update',reference:randomRef('KRSU'),amount:Number(amount),status:'succeeded',provider_metadata:{original_reference:reference,cycles,frequency,startDate,active},created_by:createdBy});return{result};}
export async function deleteNetcashSubscription({reference,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'payNowServiceKey','Pay Now Service Key');const text=await payNow('DeleteSubscription',{M1:key,P2:reference});const result=String(tag(text,'DeleteSubscriptionResult')||tag(text,'String')||'').trim();if(result!=='000')throw new HttpError(409,`Netcash subscription cancellation failed (${result||'unknown'}).`,'netcash_subscription_delete_failed');await dbInsert('netcash_paynow_operations',{kind:'subscription_delete',reference:randomRef('KRSD'),status:'succeeded',provider_metadata:{original_reference:reference},created_by:createdBy});return{result};}
export async function requestNetcashRefund({transactionId,amount,loanId=null,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.paynow_refunds_enabled)throw new HttpError(409,'Netcash Pay Now refunds are disabled.','paynow_refunds_disabled');const key=requireKey(credentials,'payNowServiceKey','Pay Now Service Key');const text=await payNow('RequestCreditCardRefund',{M1:key,TransactionId:transactionId,Amount:Number(amount).toFixed(2).replace('.',',')});const result=String(tag(text,'RequestCreditCardRefundResult')||tag(text,'String')||'').trim();if(result!=='000')throw new HttpError(409,`Netcash refund request failed (${result||'unknown'}).`,'netcash_refund_failed');const ref=randomRef('KRREF');await dbInsert('netcash_paynow_operations',{loan_id:loanId,kind:'refund',reference:ref,amount:Number(amount),transaction_id:transactionId,status:'authorisation_required',provider_metadata:{original_transaction_id:transactionId},created_by:createdBy});return{result,reference:ref,authorisationRequired:true};}

export async function validateSouthAfricanId({idNumber,userId=null,loanId=null,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'accountServiceKey','Account Service Key');const id=String(idNumber||'').replace(/\D/g,'');if(id.length!==13)throw new HttpError(400,'South African ID number must contain 13 digits.','invalid_id');const text=await validation('ValidateID',{ServiceKey:key,IDNumber:id});const raw=String(tag(text,'ValidateIDResult')||tag(text,'String')||'').trim();const valid=raw==='0';await dbInsert('netcash_risk_requests',{user_id:userId,loan_id:loanId,kind:'id_validation',account_reference:userId?`USER-${String(userId).slice(0,16)}`:null,status:valid?'valid':'invalid',result:{code:raw},created_by:createdBy});return{valid,code:raw};}
function riskFile({serviceKey,svk,instruction,batchName,keys,rows}){const sum=0;return[`H\t${serviceKey}\t1\t${instruction}\t${batchName}\t${yyyymmdd()}\t${svk||NETCASH_DEFAULT_SVK}`,`K\t${keys.join('\t')}`,...rows.map(r=>`T\t${r.join('\t')}`),`F\t${rows.length}\t${sum}\t9999`].join('\n');}
export async function submitIdVerification({userId,loanId=null,reasonCode=32,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.id_verification_enabled)throw new HttpError(409,'Netcash ID Verification is disabled.','id_verification_disabled');const key=requireKey(credentials,'riskServiceKey','Risk Reports Service Key');const p=(await dbSelect('customer_profiles',{select:'*',id:`eq.${userId}`,limit:1}))?.[0];if(!p)throw new HttpError(404,'Client profile not found.','client_profile_required');const batchName=`KR-IDV-${Date.now().toString(36)}`,ref=`IDV${String(userId).replace(/-/g,'').slice(0,18)}`;const file=riskFile({serviceKey:key,svk:config.software_vendor_key,instruction:'CD14',batchName,keys:[101,111,113,114,450,301,302,303],rows:[[ref,p.id_number||'',String(p.last_name||'').replace(/[^A-Za-z ]/g,''),String(p.first_name||'').replace(/[^A-Za-z ]/g,''),reasonCode,userId,loanId||'','KredRun']]});const fileToken=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,fileToken).catch(()=> 'FILE NOT READY');const reportXml=await nif('RequestCreditDataReport',{ServiceKey:key,FileToken:fileToken}).catch(()=>null);const report=reportXml?tag(reportXml,'RequestCreditDataReportResult')||tag(reportXml,'String'):null;const row=(await dbInsert('netcash_risk_requests',{user_id:userId,loan_id:loanId,kind:'id_verification',account_reference:ref,file_token:fileToken,status:report?'completed':'processing',result:{load_status:compactStatus(load).status,report_base64:report||null,reason_code:reasonCode},created_by:createdBy}))?.[0];return{request:row,reportReady:Boolean(report)};}
export async function submitBulkAvs({userIds,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.bulk_avs_enabled)throw new HttpError(409,'Netcash Bulk AVS is disabled.','bulk_avs_disabled');const key=requireKey(credentials,'riskServiceKey','Risk Reports Service Key');const ids=[...new Set((userIds||[]).filter(v=>UUID.test(String(v))))].slice(0,500);if(!ids.length)throw new HttpError(400,'Choose at least one client.','clients_required');const profiles=await dbSelect('customer_profiles',{select:'*',id:`in.(${ids.join(',')})`,limit:500});const rows=[];for(const p of profiles||[]){if(!p.id_number||!p.bank_account_number||!p.branch_code)continue;rows.push([`AVS${String(p.id).replace(/-/g,'').slice(0,18)}`,p.id_number,1,1,p.bank_account_holder||p.last_name||'',bankAccountTypeCode(p.bank_account_type),String(p.branch_code).replace(/\D/g,'').padStart(6,'0'),0,String(p.bank_account_number).replace(/\D/g,''),p.id,'','KredRun']);}if(!rows.length)throw new HttpError(409,'Selected clients do not have complete AVS bank details.','avs_data_incomplete');const batchName=`KR-BULK-AVS-${Date.now().toString(36)}`;const file=riskFile({serviceKey:key,svk:config.software_vendor_key,instruction:'CD35',batchName,keys:[101,126,127,131,132,133,134,135,136,301,302,303],rows});const fileToken=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,fileToken).catch(()=> 'FILE NOT READY');const reportXml=await nif('RequestAVSReport',{ServiceKey:key,FileToken:fileToken}).catch(()=>null);const report=reportXml?tag(reportXml,'RequestAVSReportResult')||tag(reportXml,'String'):null;const req=(await dbInsert('netcash_risk_requests',{kind:'bulk_avs',file_token:fileToken,status:report?'completed':'processing',result:{batch_name:batchName,count:rows.length,load_status:compactStatus(load).status,report:report||null},created_by:createdBy}))?.[0];return{request:req,count:rows.length,reportReady:Boolean(report)};}

function tokenState(userId){const secret=String(process.env.PROVIDER_CREDENTIALS_KEY||process.env.SUPABASE_SERVICE_ROLE_KEY||'');return crypto.createHmac('sha256',secret).update(`netcash-token:${userId}`).digest('hex');}
async function encryptTokenizationUrl(url){const body=`<url>${xml(url)}</url>`;const text=await soap11(SECURITY_URL,'GetEncryptedUrl',body,'http://tempuri.org/',20000);const encrypted=tag(text,'GetEncryptedUrlResult');if(!encrypted)throw new HttpError(502,'Netcash did not return an encrypted tokenisation URL.','netcash_tokenization_url_failed');return`${TOKEN_BASE_URL}${encrypted}`;}
export async function createCardTokenizationSession({userId,origin}){const{config,credentials}=await context();requireEnabled(config);if(!config.card_tokenization_enabled)throw new HttpError(409,'Netcash card tokenisation is disabled.','card_tokenization_disabled');const pciKey=requireKey(credentials,'pciVaultKey','PCI Vault Key');const caller=`${String(origin).replace(/\/$/,'')}/api/netcash?action=card_token_return&user=${encodeURIComponent(userId)}&state=${tokenState(userId)}`;const raw=`http://cde.netcash.co.za/Site/TokeniseCard.aspx?PciKey=${encodeURIComponent(pciKey)}&bbc=%23ffffff&ff=Arial&fs=14px&bc=%23777777&btnbbc=%23f1f1f1&btnc=%23777777&caller=${encodeURIComponent(caller)}`;return{url:await encryptTokenizationUrl(raw)};}
export async function saveCardTokenReturn({userId,state,form}){if(!UUID.test(String(userId))||state!==tokenState(userId))throw new HttpError(403,'Invalid Netcash card tokenisation return.','invalid_tokenization_state');const token=String(form.Token||form.token||'').trim(),masked=String(form.MaskedNumber||form.maskedNumber||'').trim();if(!token||!masked)throw new HttpError(400,'Netcash card tokenisation response is incomplete.','invalid_tokenization_return');const result=await supabaseRequest('/rest/v1/netcash_card_tokens?on_conflict=user_id,provider_token',{method:'POST',body:{user_id:userId,provider_token:token,masked_number:masked,card_name:String(form.CardNme||form.cardName||''),expiry_month:Number(form.ExpiryMonth||0)||null,expiry_year:Number(form.ExpiryYear||0)||null,status:'active',provider_metadata:{source:'netcash_tokenization_gui'},updated_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=representation'});return result?.[0];}
export async function submitCreditCardDebitOrder({loanId,scheduleId,cardTokenId,actionDate=null,instruction='same_day',createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.credit_card_debit_orders_enabled)throw new HttpError(409,'Credit-card debit orders are disabled.','card_debit_disabled');const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0],schedule=(await dbSelect('repayment_schedule',{select:'*',id:`eq.${scheduleId}`,limit:1}))?.[0],card=(await dbSelect('netcash_card_tokens',{select:'*',id:`eq.${cardTokenId}`,limit:1}))?.[0];if(!loan||!schedule||!card||card.user_id!==loan.user_id)throw new HttpError(409,'Loan, instalment and tokenised card must belong to the same client.','card_debit_context_invalid');const remaining=Number(schedule.amount_due)-Number(schedule.amount_paid||0);if(!(remaining>0))throw new HttpError(409,'This instalment has no amount left to collect.','instalment_paid');const inst=instruction==='two_day'?'TwoDay':'SameDay';const requested=actionDate||schedule.due_date||zaToday();const validDate=await requestActionDate(key,requested,inst,true)||requested;const created=(await dbInsert('netcash_card_debit_orders',{user_id:loan.user_id,loan_id:loan.id,schedule_id:schedule.id,card_token_id:card.id,amount:remaining,action_date:validDate,instruction,status:'initializing',created_by:createdBy}))?.[0];const batchName=`KR-CARD-${Date.now().toString(36)}`;const cardType=String(card.card_type||'').toLowerCase().includes('visa')?2:1;const file=[`H\t${key}\t1\t${inst}\t${batchName}\t${yyyymmdd(validDate)}\t${config.software_vendor_key||NETCASH_DEFAULT_SVK}`,'K\t101\t102\t131\t132\t133\t134\t135\t136\t137\t162\t301\t302\t303',['T',loan.account_number||created.id,String(card.card_name||'Cardholder'),2,card.card_name||'',cardType,String(card.expiry_month||'').padStart(2,'0'),String(card.expiry_year||''),card.provider_token,card.masked_number,Math.round(remaining*100),created.id,loan.id,schedule.id].join('\t'),'F\t1\t0\t9999'].join('\n');try{const fileToken=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,fileToken).catch(()=> 'FILE NOT READY');let auth={status:'required'};if(config.auto_batch_authorization_enabled&&config.auto_batch_authorization_indemnity_confirmed){try{const a=await authoriseNetcashBatch(key,batchName);auth={status:'authorised',batchId:a.batchId};}catch{}}const updated=(await dbUpdate('netcash_card_debit_orders',{id:`eq.${created.id}`},{status:auth.status==='authorised'?'authorised':'unauthorised',batch_name:batchName,file_token:fileToken,batch_id:auth.batchId||null,authorisation_status:auth.status,provider_result:{load_status:compactStatus(load).status},updated_at:new Date().toISOString()}))?.[0];return updated||created;}catch(error){await dbUpdate('netcash_card_debit_orders',{id:`eq.${created.id}`},{status:'failed',last_error:String(error.message||error).slice(0,500),updated_at:new Date().toISOString()}).catch(()=>{});throw error;}}

export async function syncBlockedAccounts({startDate,endDate}){const{config,credentials}=await context();requireEnabled(config);const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const text=await nif('RetrieveBlockedAccounts',{ServiceKey:key,StartDate:yyyymmdd(startDate),EndDate:yyyymmdd(endDate)},{methodParameters:true});const errorCode=tag(text,'ErrorCode');if(errorCode&&errorCode!=='000')throw new HttpError(409,`Netcash blocked-account lookup failed (${errorCode}).`,'blocked_accounts_failed');const rows=[];for(const block of blocks(text,'BlockedAccount')){const item={accountName:tag(block,'AccountName'),netcashAccountNumber:tag(block,'AccountNumber'),actionDate:tag(block,'ActionDate'),bankAccountMasked:tag(block,'BankAccountNumber'),blacklistType:tag(block,'BlackListType'),branchCode:tag(block,'BranchCode'),dateBlocked:tag(block,'DateBlocked'),description:tag(block,'Description'),unpaidCode:tag(block,'UnpaidCode')};const providerKey=sha(JSON.stringify(item));await supabaseRequest('/rest/v1/netcash_blocked_accounts?on_conflict=provider_key',{method:'POST',body:{provider_key:providerKey,account_name:item.accountName,netcash_account_number:item.netcashAccountNumber,action_date:item.actionDate&&/^\d{8}$/.test(item.actionDate)?`${item.actionDate.slice(0,4)}-${item.actionDate.slice(4,6)}-${item.actionDate.slice(6,8)}`:null,bank_account_masked:item.bankAccountMasked,blacklist_type:item.blacklistType,branch_code:item.branchCode,date_blocked:item.dateBlocked&&/^\d{8}$/.test(item.dateBlocked)?`${item.dateBlocked.slice(0,4)}-${item.dateBlocked.slice(4,6)}-${item.dateBlocked.slice(6,8)}`:null,description:item.description,unpaid_code:item.unpaidCode,provider_result:item,updated_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=minimal'});rows.push(item);}await dbUpdate('netcash_config',{id:'eq.true'},{blocked_accounts_last_synced_at:new Date().toISOString(),updated_at:new Date().toISOString()});return rows;}

export function parseBulkStatementFile(text){let fileDate=null,svk=null,current=null;const result=[];for(const line of String(text||'').split(/\r?\n/)){if(!line.trim())continue;const f=line.split('\t');if(f[0]==='FH'){fileDate=f[1];svk=f[2]||null;continue;}if(f[0]==='SH'){current={statementDate:f[1],accountNumber:f[2],accountServiceKey:f[3]};continue;}if(f[0]==='SF'){current=null;continue;}if(f[0]==='FF')break;if(!current||f.length<7)continue;const d=f[0];if(!/^\d{8}$/.test(d))continue;result.push({fileDate,softwareVendorKey:svk,statementDate:current.statementDate,netcashAccountNumber:current.accountNumber,accountServiceKey:current.accountServiceKey,transactionDate:d,transactionType:String(f[1]||'').toUpperCase(),transactionId:String(f[2]||''),description:f[3]||'',amount:Math.abs(Number(f[4]||0))/100,symbol:f[5]||'',vat:Math.abs(Number(f[6]||0))/100,extra1:f[7]||'',extra2:f[8]||'',extra3:f[9]||'',raw:f});}return result;}
export async function ingestBulkStatement(text){const{config,credentials}=await context();if(!config.bulk_statement_enabled)throw new HttpError(409,'Netcash Bulk Statement is disabled.','bulk_statement_disabled');const entries=parseBulkStatementFile(text);let received=0,processed=0,reviewRequired=0;for(const row of entries){const body={file_date:row.fileDate&&`${row.fileDate.slice(0,4)}-${row.fileDate.slice(4,6)}-${row.fileDate.slice(6,8)}`,software_vendor_key:row.softwareVendorKey,statement_date:`${row.statementDate.slice(0,4)}-${row.statementDate.slice(4,6)}-${row.statementDate.slice(6,8)}`,netcash_account_number:row.netcashAccountNumber,account_service_key_hash:sha(row.accountServiceKey),transaction_type:row.transactionType,transaction_id:row.transactionId,description:row.description,amount:row.amount,symbol:row.symbol,vat:row.vat,extra1:row.extra1||null,extra2:row.extra2||null,extra3:row.extra3||null,raw:{fields:row.raw}};const saved=await supabaseRequest('/rest/v1/netcash_bulk_statement_entries?on_conflict=netcash_account_number,transaction_type,transaction_id',{method:'POST',body,prefer:'resolution=ignore-duplicates,return=representation'});if(!saved?.[0])continue;received+=1;if(row.netcashAccountNumber===config.account_number&&credentials.accountServiceKey&&sha(row.accountServiceKey)===sha(credentials.accountServiceKey)){const r=await processFullStatementTransaction(row).catch(error=>({status:'review_required',reason:error.message}));await dbUpdate('netcash_bulk_statement_entries',{id:`eq.${saved[0].id}`},{processing_status:r.status==='review_required'?'review_required':'processed',processing_message:r.reason||null,processed_at:new Date().toISOString()});if(r.status==='review_required')reviewRequired+=1;else processed+=1;}}return{entries:entries.length,received,processed,reviewRequired};}

const DIRECT_SUCCESS=new Set(['TDD','SDD','DCS']);const CARD_SUCCESS=new Set(['TDC','SDC']);const DIRECT_RETURN=new Set(['DRU','DCX','DCD']);const CARD_RETURN=new Set(['DCU','DRC']);const PAYOUT_SUCCESS=new Set(['CRP','DCP','CRT','PSC']);const PAYOUT_RETURN=new Set(['CRU','CRR','CRJ','PCR','PCI','PCU']);const PAYNOW_SUCCESS=new Set(['PNC','PNP','PNM','PNE','PIA','PIS','PIF','PVC','PFC','PGC','PMW','PME']);const PAYNOW_REFUND=new Set(['PNR','PNX','PIR','PVR','PFR','PGR']);const RM_CODES=new Set(['RMS','RMX','RMT','RMD','RPS','RMM']);
function rowDate(row){const d=String(row.statementDate||row.transactionDate||'').replace(/-/g,'');return/^\d{8}$/.test(d)?`${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T12:00:00+02:00`:new Date().toISOString();}
async function instructionFromRow(row){if(UUID.test(String(row.extra1||''))){const x=await dbSelect('netcash_collection_instructions',{select:'*',id:`eq.${row.extra1}`,limit:1});if(x?.[0])return x[0];}if(UUID.test(String(row.extra3||''))){const x=await dbSelect('netcash_collection_instructions',{select:'*',schedule_id:`eq.${row.extra3}`,limit:1});if(x?.[0])return x[0];}return null;}
export async function processFullStatementTransaction(row){const type=String(row.transactionType||'').toUpperCase(),amount=Math.abs(Number(row.amount||0)),at=rowDate(row);
  if(DIRECT_SUCCESS.has(type)||DIRECT_RETURN.has(type)){const i=await instructionFromRow(row);if(!i)return{status:'review_required',reason:'Could not map debit-order statement row.'};if(DIRECT_SUCCESS.has(type))return await dbRpc('process_netcash_collection_success',{p_instruction_id:i.id,p_provider_reference:row.transactionId,p_paid_amount:amount,p_paid_at:at,p_transaction_type:type});return await dbRpc('process_netcash_collection_return',{p_instruction_id:i.id,p_provider_reference:row.transactionId,p_amount:amount||Number(i.amount),p_returned_at:at,p_transaction_type:type,p_reason_code:(String(row.description||'').match(/code\s*:?\s*(\d{1,2})/i)||[])[1]||null});}
  if(CARD_SUCCESS.has(type)||CARD_RETURN.has(type)){let c=null;if(UUID.test(String(row.extra1||'')))c=(await dbSelect('netcash_card_debit_orders',{select:'*',id:`eq.${row.extra1}`,limit:1}))?.[0];if(!c)return{status:'review_required',reason:'Could not map tokenised card debit.'};await dbUpdate('netcash_card_debit_orders',{id:`eq.${c.id}`},{status:CARD_SUCCESS.has(type)?'paid':'returned',transaction_id:row.transactionId,updated_at:new Date().toISOString()});if(CARD_SUCCESS.has(type)&&c.schedule_id){const i=(await dbSelect('netcash_collection_instructions',{select:'*',schedule_id:`eq.${c.schedule_id}`,limit:1}))?.[0];if(i)return await dbRpc('process_netcash_collection_success',{p_instruction_id:i.id,p_provider_reference:row.transactionId,p_paid_amount:amount,p_paid_at:at,p_transaction_type:type});}return{status:CARD_SUCCESS.has(type)?'paid':'returned'};}
  if(PAYOUT_SUCCESS.has(type)||PAYOUT_RETURN.has(type)){let p=null;if(UUID.test(String(row.extra1||'')))p=(await dbSelect('netcash_payouts',{select:'*',id:`eq.${row.extra1}`,limit:1}))?.[0];if(!p)return{status:'review_required',reason:'Could not map creditor payout.'};return await dbRpc('process_netcash_payout_statement',{p_payout_id:p.id,p_transaction_id:row.transactionId,p_transaction_type:type,p_amount:amount,p_processed_at:at,p_is_return:PAYOUT_RETURN.has(type)});}
  if(PAYNOW_SUCCESS.has(type)){let req=null;if(UUID.test(String(row.extra1||'')))req=(await dbSelect('netcash_payment_requests',{select:'*',id:`eq.${row.extra1}`,limit:1}))?.[0];if(req)return await dbRpc('process_netcash_payment',{p_request_id:req.id,p_provider_reference:row.transactionId,p_paid_amount:amount,p_paid_at:at,p_channel:type});const op=(await dbSelect('netcash_paynow_operations',{select:'*',reference:`eq.${row.extra1||row.extra2||''}`,limit:1}))?.[0];if(op){await dbUpdate('netcash_paynow_operations',{id:`eq.${op.id}`},{status:'succeeded',transaction_id:row.transactionId,updated_at:new Date().toISOString()});return{status:'succeeded'};}return{status:'review_required',reason:'Could not map Pay Now transaction.'};}
  if(PAYNOW_REFUND.has(type)){const op=(await dbSelect('netcash_paynow_operations',{select:'*',transaction_id:`eq.${row.transactionId}`,limit:1}).catch(()=>[]))?.[0];if(op)await dbUpdate('netcash_paynow_operations',{id:`eq.${op.id}`},{status:'refunded',updated_at:new Date().toISOString()});return{status:'refund'};}
  if(RM_CODES.has(type)){return{status:'registered_mandate',transactionType:type};}
  if(type==='ELM'||type==='DCM'||type==='DCT'||type==='DPS')return{status:'mandate_event',transactionType:type};
  return{status:'informational',transactionType:type};
}

export async function requestRegisteredMandateFallback({loanId,createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.registered_mandate_enabled)throw new HttpError(409,'Registered Mandate fallback is disabled.','registered_mandate_disabled');const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0],contract=(await dbSelect('netcash_contracts',{select:'*',loan_id:`eq.${loanId}`,limit:1}))?.[0],profile=loan?(await dbSelect('customer_profiles',{select:'*',id:`eq.${loan.user_id}`,limit:1}))?.[0]:null,schedule=loan?(await dbSelect('repayment_schedule',{select:'*',loan_id:`eq.${loan.id}`,order:'instalment_number.asc',limit:1}))?.[0]:null;if(!loan||!contract||!profile||!schedule)throw new HttpError(409,'Loan mandate data is incomplete.','registered_mandate_data_missing');if(contract.debicheck_auth_mode==='tt1')throw new HttpError(409,'Registered Mandate fallback is not available for TT1. Use TT2 batch authentication.','registered_mandate_not_tt1');const batchName=`KR-RM-${Date.now().toString(36)}`,amount=Math.round(Number(loan.instalment_amount||schedule.amount_due)*100),first=Math.round((Number(schedule.amount_due)-Number(schedule.amount_paid||0))*100);const keyFields=[101,102,111,127,132,133,134,136,201,202,242,243,246,247,248,250,616];const day=`MNTH_${String(schedule.due_date).slice(8,10)}`;const file=[`H\t${key}\t1\tDebiCheckAuthentication\t${batchName}\t${yyyymmdd()}\t${config.software_vendor_key||NETCASH_DEFAULT_SVK}`,`K\t${keyFields.join('\t')}`,['T',contract.account_reference,`${profile.first_name||''} ${profile.last_name||''}`.trim(),profile.id_number,1,profile.bank_account_holder,bankAccountTypeCode(profile.bank_account_type),String(profile.branch_code).replace(/\D/g,'').padStart(6,'0'),profile.bank_account_number,profile.email||'',String(profile.mobile||'').replace(/\D/g,'').slice(-11),config.debicheck_template_id,amount,first!==amount?1:0,first,yyyymmdd(schedule.due_date),day,1].join('\t'),'F\t1\t0\t9999'].join('\n');const fileToken=await batchFileUpload(key,file);const load=await requestFileUploadReport(key,fileToken).catch(()=> 'FILE NOT READY');await dbUpdate('netcash_contracts',{id:`eq.${contract.id}`},{provider_metadata:{...(contract.provider_metadata||{}),registered_mandate:{requested:true,provider_legacy_rms_field:616,file_token:fileToken,batch_name:batchName,load_status:compactStatus(load).status,requested_at:new Date().toISOString(),created_by:createdBy}},updated_at:new Date().toISOString()});return{fileToken,batchName,loadStatus:compactStatus(load).status,registeredMandate:true};}
